flow.typescript:
// D9 · Part 0~6 · 오늘의 흐름 전체 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_flow.ts
//   받아쓰기 → 강제 정렬로 단어 시각 → 목소리 지문으로 화자 나누기 → 단어에 화자 붙여 회의록, 한 흐름을 아주 작게 돌려 보기
// 대체 경로: WhisperX · pyannote · speechbrain 모델은 쓰지 않고, 합성음(음높이가 다른 세 목소리)과 손으로 만든 시각표로 같은 단계를 흉내 낸다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const NFFT = 32768;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 1;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

function voice(f0: number, dur: number): Float64Array {
  const n = Math.floor(dur * SR);
  const y = new Float64Array(n);
  for (let h = 1; h < 30 && f0 * h < SR / 2; h++) {
    const amp = 1 / h ** (0.8 + f0 / 400);
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin((2 * Math.PI * f0 * h * i) / SR);
  }
  const peak = Math.max(...y.map(Math.abs));
  return y.map((v) => (0.3 * v) / peak + 0.01 * randn());
}

function fft(re: Float64Array, im: Float64Array): void {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const ur = re[i + k];
        const ui = im[i + k];
        const vr = re[i + k + len / 2] * wr - im[i + k + len / 2] * wi;
        const vi = re[i + k + len / 2] * wi + im[i + k + len / 2] * wr;
        re[i + k] = ur + vr;
        im[i + k] = ui + vi;
        re[i + k + len / 2] = ur - vr;
        im[i + k + len / 2] = ui - vi;
      }
    }
  }
}

function embed(y: Float64Array, bands: number = 24): number[] {
  const re = new Float64Array(NFFT);
  const im = new Float64Array(NFFT);
  y.forEach((v, i) => {
    re[i] = v * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (y.length - 1)));
  });
  fft(re, im);
  const out: number[] = [];
  for (let b = 0; b < bands; b++) {
    const k0 = Math.floor((60 * (SR / 2 / 60) ** (b / bands) * NFFT) / SR);
    const k1 = Math.max(k0, Math.floor((60 * (SR / 2 / 60) ** ((b + 1) / bands) * NFFT) / SR));
    let s = 0;
    for (let k = k0; k <= k1; k++) s += Math.log(Math.hypot(re[k], im[k]) + 1e-9);
    out.push(s / (k1 - k0 + 1));
  }
  return out;
}

// 1) 세 사람이 번갈아 말하는 합성 회의: 사람마다 음높이가 다르다
const VOICES: Record<string, number> = { 김팀장: 110, 이연구원: 210, 박대리: 150 };
const SCRIPT: [string, string][] = [["김팀장", "오늘 회의를 시작합니다"], ["이연구원", "모델은 정했습니다"], ["박대리", "구분이 안 됩니다"]];
const pieces: [string, number, number, Float64Array][] = [];
const words: [string, number, number][] = [];
let cursor = 0;
for (const [spk, text] of SCRIPT) {
  const ws = text.split(" ");
  const dur = 0.6 * ws.length;
  pieces.push([spk, cursor, cursor + dur, voice(VOICES[spk], dur)]);
  ws.forEach((w, i) => words.push([w, cursor + 0.6 * i, cursor + 0.6 * (i + 1) - 0.1])); // 2) 단어 시각 (정렬 결과라고 가정)
  cursor += dur + 0.5;
}
console.log(`회의 길이 ${cursor.toFixed(1)}초, 발화 ${pieces.length}개, 단어 ${words.length}개`);
check(words.length === 8 && Math.abs(cursor - 6.3) < 1e-9, "발화 3개, 단어 8개예요.");

// 3) 목소리 지문: 평균 로그 스펙트럼 띠 -> 가장 닮은 사람 찾기
const enroll: Record<string, number[]> = {};
for (const [n, f0] of Object.entries(VOICES)) enroll[n] = embed(voice(f0, 1.5)); // 등록해 둔 목소리
const meanE = enroll["김팀장"].map((_, j) => Object.values(enroll).reduce((s, e) => s + e[j], 0) / 3);
const cos = (a: number[], b: number[]): number => {
  const x = a.map((v, j) => v - meanE[j]);
  const y = b.map((v, j) => v - meanE[j]);
  return x.reduce((s, v, j) => s + v * y[j], 0) / (Math.hypot(...x) * Math.hypot(...y));
};
const who = pieces.map(([, , , y]) => {
  const e = embed(y);
  return Object.keys(enroll).reduce((best, n) => (cos(e, enroll[n]) > cos(e, enroll[best]) ? n : best));
});
console.log("지문으로 맞힌 화자:", who.join(", "));
check(who.join() === SCRIPT.map((s) => s[0]).join(), "등록한 목소리와 가장 닮은 사람이 정답이에요.");

// 4) 단어에 화자 붙이기(가장 많이 겹치는 발화) -> 같은 화자는 한 줄로
const spkOf = (s: number, e: number): string => {
  const ov = pieces.map(([, a, b], k) => [Math.max(0, Math.min(e, b) - Math.max(s, a)), who[k]] as [number, string]);
  return ov.reduce((b, o) => (o[0] > b[0] ? o : b))[1];
};
const lines: [string, string[]][] = [];
for (const [w, s, e] of words) {
  const spk = spkOf(s, e);
  const last = lines[lines.length - 1];
  if (last && last[0] === spk) last[1].push(w);
  else lines.push([spk, [w]]);
}
for (const [spk, ws] of lines) console.log(`${spk}: ${ws.join(" ")}`);
check(lines.map(([s, w]) => `${s}: ${w.join(" ")}`).join("|") === SCRIPT.map(([s, t]) => `${s}: ${t}`).join("|"), "회의록이 대본과 같아야 해요.");

stamps.typescript:
// D9 · Part 1 · 문장 시각 vs 단어 시각: Whisper 단어 시각의 한계와 발화 경계 오차 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_stamps.ts
//   정답 발화 구간(TURNS)을 알고 있을 때, 각 발화의 첫 단어 시작 · 마지막 단어 끝이 정답에서 얼마나 벗어났는지(발화 경계 오차)를 두 방식으로 재서 비교
// 대체 경로: faster-whisper 의 word_timestamps(attention 으로 추정)와 WhisperX 정렬 결과 대신, '정답 시각 + 오차(표준편차 150 ms vs 20 ms)' 로 흉내 낸 가짜 단어 시각을 쓴다.
type Word = { word: string; start: number; end: number };

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 1;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

const TURNS: [string, number, number, string][] = [
  ["김팀장", 0.0, 4.0, "오늘 회의는 음성 비서 프로젝트 진행 상황을 점검하겠습니다."],
  ["이연구원", 4.5, 8.5, "받아쓰기 모델은 위스퍼 스몰로 정했고 정확도는 충분합니다."],
  ["박대리", 9.0, 12.4, "그런데 회의 녹음에서 누가 말했는지 구분이 안 됩니다."],
  ["김팀장", 13.0, 16.0, "그래서 오늘 화자 분리를 붙여 보자는 겁니다."],
];

const trueWords: Word[] = []; // 정답 단어 시각 (글자 수에 비례 + 약간의 불규칙)
for (const [, a, b, text] of TURNS) {
  const ws = text.split(" ");
  const wt = ws.map((w) => w.length * (0.7 + 0.6 * uni()));
  const total = wt.reduce((s, v) => s + v, 0);
  let acc = 0;
  for (let i = 0; i < ws.length; i++) {
    const s = a + ((b - a) * acc) / total;
    acc += wt[i];
    trueWords.push({ word: ws[i], start: s, end: a + ((b - a) * acc) / total - 0.05 });
  }
  trueWords[trueWords.length - 1].end = b; // 발화의 마지막 단어는 발화 끝에서 끝난다
}

const estimate = (sigma: number): Word[] =>
  trueWords.map((w) => {
    const s = Math.max(0, w.start + sigma * randn());
    return { word: w.word, start: s, end: Math.max(s + 0.05, w.end + sigma * randn()) };
  });

const turnOf = (t: number): number => {
  const d = TURNS.map(([, a, b]) => (t >= a && t <= b ? 0 : Math.min(Math.abs(t - a), Math.abs(t - b))));
  return d.indexOf(Math.min(...d));
};

function boundaryErrors(words: Word[]): number[] {
  const by = new Map<number, Word[]>();
  for (const w of words) {
    const k = turnOf((w.start + w.end) / 2);
    by.set(k, [...(by.get(k) ?? []), w]);
  }
  const errs: number[] = [];
  for (const k of [...by.keys()].sort((a, b) => a - b)) {
    const ws = by.get(k)!;
    errs.push(Math.abs(ws[0].start - TURNS[k][1]), Math.abs(ws[ws.length - 1].end - TURNS[k][2]));
  }
  return errs;
}

const fw = estimate(0.15); // Whisper: attention 으로 추정 -> 흔들림이 큼
const wx = estimate(0.02); // WhisperX: 프레임(20 ms) 단위로 강제 정렬 -> 정확
console.log("단어 앞 4개 (정답 / Whisper 추정 / 정렬):");
for (let i = 0; i < 4; i++) console.log(`  ${trueWords[i].word} ${trueWords[i].start.toFixed(2)} / ${fw[i].start.toFixed(2)} / ${wx[i].start.toFixed(2)}`);
const errFw = boundaryErrors(fw);
const errWx = boundaryErrors(wx);
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
console.log(`발화 경계 오차: Whisper 평균 ${(mean(errFw) * 1000).toFixed(0)} ms, 최대 ${(Math.max(...errFw) * 1000).toFixed(0)} ms | 정렬 평균 ${(mean(errWx) * 1000).toFixed(0)} ms`);
check(fw.every((w) => w.end >= w.start) && fw.length === trueWords.length, "단어마다 끝 시각이 시작 시각보다 크거나 같아야 해요.");
check(mean(errWx) < mean(errFw), "강제 정렬이 attention 추정보다 경계 오차가 작아요.");

trellis.typescript:
// D9 · Part 2 · 강제 정렬(forced alignment): 격자(trellis) 따라가기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_trellis.ts
//   정답 글자 순서가 주어졌을 때 프레임 x 글자 격자에 '머물기(blank) / 다음 글자로 넘어가기' 점수를 채우고(log 확률 덧셈), 뒤에서 따라가며 각 글자의 시작 프레임 -> 초를 구한다
// 대체 경로: wav2vec2 정렬 모델의 출력 대신, 글자가 튀어나오는 프레임(2·6·10)에 높은 확률을 둔 15프레임짜리 장난감 확률표를 쓴다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const VOCAB = ["_", "가", "나", "다"]; // 0번 = blank
const tokens = [1, 2, 3]; // 정답 글자: 가 -> 나 -> 다
const T = 15;
const P = Array.from({ length: T }, () => [0.94, 0.02, 0.02, 0.02]); // 대부분 blank
[2, 6, 10].forEach((f, k) => {
  P[f][k + 1] = 0.9; // 글자가 튀어나오는 프레임
  P[f][0] = 0.08;
});
const em = P.map((row) => {
  const s = row.reduce((a, b) => a + b, 0);
  return row.map((v) => Math.log(v / s)); // log 확률 (곱 -> 덧셈)
});

function getTrellis(em: number[][], tokens: number[], blank: number = 0): number[][] {
  const T = em.length;
  const J = tokens.length;
  const trellis = Array.from({ length: T + 1 }, () => new Array(J + 1).fill(-Infinity));
  trellis[0][0] = 0;
  for (let t = 0; t < T; t++) {
    trellis[t + 1][0] = trellis[t][0] + em[t][blank]; // 아직 첫 글자 전 (blank 만)
    for (let j = 1; j <= J; j++) {
      const stay = trellis[t][j] + em[t][blank]; // 머물기
      const move = trellis[t][j - 1] + em[t][tokens[j - 1]]; // 다음 글자로 넘어가기
      trellis[t + 1][j] = Math.max(stay, move);
    }
  }
  return trellis;
}

function backtrack(trellis: number[][], em: number[][], tokens: number[], blank: number = 0): number[] {
  let t = em.length;
  let j = tokens.length;
  const starts: number[] = new Array(tokens.length).fill(-1);
  while (t > 0 && j > 0) {
    const stay = trellis[t - 1][j] + em[t - 1][blank];
    const move = trellis[t - 1][j - 1] + em[t - 1][tokens[j - 1]];
    if (move > stay) {
      // 여기서 j번째 글자로 넘어옴 = 그 글자의 시작
      starts[j - 1] = t - 1;
      j--;
    }
    t--;
  }
  return starts;
}

const trellis = getTrellis(em, tokens);
console.log("격자 마지막 칸(모든 글자를 쓴 최고 점수):", trellis[T][tokens.length].toFixed(3));
check(Number.isFinite(trellis[T][tokens.length]) && trellis[0][0] === 0, "격자 오른쪽 아래 칸에 모든 글자를 쓴 점수가 있어야 해요.");

const FRAME_SEC = 320 / SR; // 프레임 하나 = 몇 초? (wav2vec2 전체 보폭 320샘플)
const startFrames = backtrack(trellis, em, tokens);
const ends = [...startFrames.slice(1), T];
startFrames.forEach((a, k) => {
  const b = ends[k];
  console.log(`'${VOCAB[tokens[k]]}': 프레임 ${String(a).padStart(2)} ~ ${String(b - 1).padStart(2)}  ->  ${(a * FRAME_SEC).toFixed(2)}초 ~ ${(b * FRAME_SEC).toFixed(2)}초`);
});
check(Math.abs(FRAME_SEC - 0.02) < 1e-9 && startFrames.join() === "2,6,10", "320샘플 / 16000 = 0.02초(20 ms), 글자 시작 프레임은 2, 6, 10 이에요.");

wxpipe.typescript:
// D9 · Part 3 · WhisperX 파이프라인: 거친 문장 시각 → 단어별 강제 정렬 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_wxpipe.ts
//   1) 받아쓰기는 문장 시작·끝만 안다 → 단어는 글자 수에 비례해 나눠 가진 '거친' 시각  2) 소리와 단어 순서를 격자로 정렬해 단어 시각을 정확하게  3) SRT 자막 시각 문자열
// 대체 경로: WhisperX · wav2vec2 정렬 모델 대신, 단어가 시작하는 프레임에 확률이 튀는 가짜 확률표(±1프레임 흔들림)에 같은 격자 정렬을 적용한다.
const FRAME = 0.02; // 프레임 하나 = 20 ms

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 2;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};

const SEGMENTS: [number, number, string][] = [
  [0.0, 4.0, "오늘 회의는 음성 비서 프로젝트 진행 상황을 점검하겠습니다."],
  [4.5, 8.5, "받아쓰기 모델은 위스퍼 스몰로 정했고 정확도는 충분합니다."],
];

const words: string[] = [];
const trueStart: number[] = [];
const coarseStart: number[] = [];
for (const [a, b, text] of SEGMENTS) {
  const ws = text.split(" ");
  const raw = ws.map((w) => w.length * (0.7 + 0.6 * uni())); // 실제로는 말하는 속도가 들쭉날쭉
  const rawSum = raw.reduce((s, v) => s + v, 0);
  const lenSum = ws.reduce((s, w) => s + w.length, 0);
  let accT = 0;
  let accC = 0;
  ws.forEach((w, i) => {
    words.push(w);
    trueStart.push(a + ((b - a) * accT) / rawSum);
    coarseStart.push(a + ((b - a) * accC) / lenSum); // 글자 수에 비례(거친 시각)
    accT += raw[i];
    accC += w.length;
  });
}

// 가짜 확률표: 단어 i 가 시작하는 프레임(+-1 흔들림)에서 단어 i 칸 확률이 튄다
const T = Math.floor(8.6 / FRAME);
const N = words.length;
const P = Array.from({ length: T }, () => [0.95, ...new Array(N).fill(0.001)]);
trueStart.forEach((s, i) => {
  const f = Math.max(0, Math.round(s / FRAME) + Math.floor(uni() * 3) - 1);
  P[f][i + 1] = 0.9;
  P[f][0] = 0.05;
});
const em = P.map((row) => {
  const s = row.reduce((a, b) => a + b, 0);
  return row.map((v) => Math.log(v / s));
});

// 격자 정렬 (D9 trellis 와 같은 방식: 머물기 vs 다음 단어로 넘어가기)
const tr = Array.from({ length: T + 1 }, () => new Array(N + 1).fill(-Infinity));
tr[0][0] = 0;
for (let t = 0; t < T; t++) {
  tr[t + 1][0] = tr[t][0] + em[t][0];
  for (let j = 1; j <= N; j++) tr[t + 1][j] = Math.max(tr[t][j] + em[t][0], tr[t][j - 1] + em[t][j]);
}
let t = T;
let j = N;
const starts: number[] = new Array(N).fill(0);
while (t > 0 && j > 0) {
  if (tr[t - 1][j - 1] + em[t - 1][j] > tr[t - 1][j] + em[t - 1][0]) {
    starts[j - 1] = t - 1;
    j--;
  }
  t--;
}
const aligned = starts.map((f) => f * FRAME);

const errCoarse = coarseStart.map((c, i) => Math.abs(c - trueStart[i]));
const errAligned = aligned.map((a, i) => Math.abs(a - trueStart[i]));
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
console.log(`단어 ${N}개 | 시작 시각 오차 평균: 거친 시각 ${(mean(errCoarse) * 1000).toFixed(0)} ms -> 정렬 후 ${(mean(errAligned) * 1000).toFixed(0)} ms`);
for (let i = 0; i < 4; i++) console.log(`  ${words[i]} 정답 ${trueStart[i].toFixed(2)} | 거친 ${coarseStart[i].toFixed(2)} | 정렬 ${aligned[i].toFixed(2)}`);
check(mean(errAligned) < mean(errCoarse) && Math.max(...errAligned) <= 0.05 + 1e-9, "정렬한 단어 시각은 정답에서 1~2프레임(20~40 ms) 안이어야 해요.");

function srtTime(sec: number): string {
  let ms = Math.round(sec * 1000); // 초 -> 밀리초
  const h = Math.floor(ms / 3_600_000);
  ms %= 3_600_000;
  const m = Math.floor(ms / 60_000);
  ms %= 60_000;
  const s = Math.floor(ms / 1000);
  ms %= 1000;
  const p = (n: number, w: number = 2): string => String(n).padStart(w, "0");
  return `${p(h)}:${p(m)}:${p(s)},${p(ms, 3)}`;
}
console.log(`자막 1줄: ${srtTime(aligned[0])} --> ${srtTime(SEGMENTS[0][1])}`);
check(srtTime(3.25) === "00:00:03,250" && srtTime(3725.5) === "01:02:05,500", "1초 = 1000밀리초");

embed.typescript:
// D9 · Part 4 · 목소리 지문(speaker embedding)과 코사인 유사도 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_embed.ts
//   세 사람의 목소리를 음높이가 다른 합성음으로 만들어 '평균 로그 스펙트럼 띠' 를 지문으로 쓰고, 코사인 유사도가 같은 사람끼리 더 높은 것을 확인
// 대체 경로: ECAPA-TDNN 화자 임베딩(모델 다운로드 필요) 대신, FFT 로 구한 24개 주파수 띠의 평균 로그 에너지를 지문 벡터로 쓴다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const VOICES: Record<string, number> = { 김팀장: 110, 이연구원: 210, 박대리: 150 }; // 이름 -> 기본 음높이(Hz)
const NFFT = 32768;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 1;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

function voice(f0: number, dur: number): Float64Array {
  const n = Math.floor(dur * SR);
  const y = new Float64Array(n);
  for (let h = 1; h < 30 && f0 * h < SR / 2; h++) {
    const amp = 1 / h ** (0.8 + f0 / 400);
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin((2 * Math.PI * f0 * h * i) / SR);
  }
  const peak = Math.max(...y.map(Math.abs));
  return y.map((v) => (0.3 * v) / peak + 0.01 * randn());
}

// 제자리 radix-2 FFT (re, im 길이는 2의 거듭제곱)
function fft(re: Float64Array, im: Float64Array): void {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const ur = re[i + k];
        const ui = im[i + k];
        const vr = re[i + k + len / 2] * wr - im[i + k + len / 2] * wi;
        const vi = re[i + k + len / 2] * wi + im[i + k + len / 2] * wr;
        re[i + k] = ur + vr;
        im[i + k] = ui + vi;
        re[i + k + len / 2] = ur - vr;
        im[i + k + len / 2] = ui - vi;
      }
    }
  }
}

function embed(y: Float64Array, bands: number = 24): number[] {
  const re = new Float64Array(NFFT);
  const im = new Float64Array(NFFT);
  y.forEach((v, i) => {
    re[i] = v * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (y.length - 1))); // 한(Hann) 창
  });
  fft(re, im);
  const mag = Array.from({ length: NFFT / 2 + 1 }, (_, k) => Math.hypot(re[k], im[k]) + 1e-9);
  const out: number[] = [];
  for (let b = 0; b < bands; b++) {
    const f0 = 60 * (SR / 2 / 60) ** (b / bands);
    const f1 = 60 * (SR / 2 / 60) ** ((b + 1) / bands);
    const k0 = Math.floor((f0 * NFFT) / SR);
    const k1 = Math.max(k0, Math.floor((f1 * NFFT) / SR));
    let s = 0;
    for (let k = k0; k <= k1; k++) s += Math.log(mag[k]);
    out.push(s / (k1 - k0 + 1));
  }
  return out;
}

const dot = (a: number[], b: number[]): number => a.reduce((s, v, i) => s + v * b[i], 0);
const cosine = (a: number[], b: number[]): number => dot(a, b) / (Math.hypot(...a) * Math.hypot(...b));

const truth: string[] = [];
for (const n of Object.keys(VOICES)) for (let i = 0; i < 3; i++) truth.push(n); // 사람마다 발화 3개
let E = truth.map((n) => embed(voice(VOICES[n] * (1 + 0.02 * randn()), 1.5)));
const meanE = E[0].map((_, j) => E.reduce((s, e) => s + e[j], 0) / E.length);
E = E.map((e) => e.map((v, j) => v - meanE[j])); // 모든 지문의 평균을 빼서 서로의 차이만 남긴다
console.log("지문 모양:", `(${E.length}, ${E[0].length})`, "(발화 수, 띠 수)");

const same: number[] = [];
const diff: number[] = [];
for (let i = 0; i < E.length; i++) {
  for (let j = i + 1; j < E.length; j++) (truth[i] === truth[j] ? same : diff).push(cosine(E[i], E[j]));
}
const mean = (a: number[]): number => a.reduce((s, v) => s + v, 0) / a.length;
console.log(`같은 사람 평균 ${mean(same).toFixed(2)}  vs  다른 사람 평균 ${mean(diff).toFixed(2)}`);
check(Math.abs(cosine([1, 0], [3, 0]) - 1) < 1e-9 && Math.abs(cosine([1, 0], [0, 2])) < 1e-9, "분모는 두 벡터 a 와 b 의 길이를 곱합니다.");
check(mean(same) > mean(diff) + 0.3, "같은 사람끼리의 유사도가 다른 사람끼리보다 훨씬 높아야 해요.");

cluster.typescript:
// D9 · Part 4 · 군집 합치기: 비슷한 지문끼리 묶어 화자 번호 매기기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_cluster.ts
//   발화마다 목소리 지문을 만들고 응집형 군집(코사인 거리 · average 연결)을 직접 구현해 참가자 수(3)만큼 묶고, 정답 화자와의 교차표를 만든다
// 대체 경로: ECAPA 화자 임베딩(모델 다운로드 필요) 대신, 음높이가 다른 합성음의 평균 로그 스펙트럼 띠(24개)를 지문으로 쓴다.
const SR = 16000; // 음성 모델 표준: 1초에 16,000번 측정 (16kHz)
const VOICES: Record<string, number> = { 김팀장: 110, 이연구원: 210, 박대리: 150 };
const NFFT = 32768;

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

let seed = 1;
const uni = (): number => {
  // mulberry32: 작지만 고르게 퍼지는 의사 난수
  seed = (seed + 0x6d2b79f5) | 0;
  let t = Math.imul(seed ^ (seed >>> 15), 1 | seed);
  t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
  return (((t ^ (t >>> 14)) >>> 0) + 0.5) / 4294967296;
};
const randn = (): number => Math.sqrt(-2 * Math.log(uni())) * Math.cos(2 * Math.PI * uni());

function voice(f0: number, dur: number): Float64Array {
  const n = Math.floor(dur * SR);
  const y = new Float64Array(n);
  for (let h = 1; h < 30 && f0 * h < SR / 2; h++) {
    const amp = 1 / h ** (0.8 + f0 / 400);
    for (let i = 0; i < n; i++) y[i] += amp * Math.sin((2 * Math.PI * f0 * h * i) / SR);
  }
  const peak = Math.max(...y.map(Math.abs));
  return y.map((v) => (0.3 * v) / peak + 0.01 * randn());
}

function fft(re: Float64Array, im: Float64Array): void {
  const n = re.length;
  for (let i = 1, j = 0; i < n; i++) {
    let bit = n >> 1;
    for (; j & bit; bit >>= 1) j ^= bit;
    j ^= bit;
    if (i < j) {
      [re[i], re[j]] = [re[j], re[i]];
      [im[i], im[j]] = [im[j], im[i]];
    }
  }
  for (let len = 2; len <= n; len <<= 1) {
    const ang = (-2 * Math.PI) / len;
    for (let i = 0; i < n; i += len) {
      for (let k = 0; k < len / 2; k++) {
        const wr = Math.cos(ang * k);
        const wi = Math.sin(ang * k);
        const ur = re[i + k];
        const ui = im[i + k];
        const vr = re[i + k + len / 2] * wr - im[i + k + len / 2] * wi;
        const vi = re[i + k + len / 2] * wi + im[i + k + len / 2] * wr;
        re[i + k] = ur + vr;
        im[i + k] = ui + vi;
        re[i + k + len / 2] = ur - vr;
        im[i + k + len / 2] = ui - vi;
      }
    }
  }
}

function embed(y: Float64Array, bands: number = 24): number[] {
  const re = new Float64Array(NFFT);
  const im = new Float64Array(NFFT);
  y.forEach((v, i) => {
    re[i] = v * (0.5 - 0.5 * Math.cos((2 * Math.PI * i) / (y.length - 1)));
  });
  fft(re, im);
  const out: number[] = [];
  for (let b = 0; b < bands; b++) {
    const k0 = Math.floor((60 * (SR / 2 / 60) ** (b / bands) * NFFT) / SR);
    const k1 = Math.max(k0, Math.floor((60 * (SR / 2 / 60) ** ((b + 1) / bands) * NFFT) / SR));
    let s = 0;
    for (let k = k0; k <= k1; k++) s += Math.log(Math.hypot(re[k], im[k]) + 1e-9);
    out.push(s / (k1 - k0 + 1));
  }
  return out;
}

const dot = (a: number[], b: number[]): number => a.reduce((s, v, i) => s + v * b[i], 0);
const cosDist = (a: number[], b: number[]): number => 1 - dot(a, b) / (Math.hypot(...a) * Math.hypot(...b));

// 응집형 군집 (average 연결): 가장 가까운 두 묶음을 하나로 합치기를 nClusters 개가 남을 때까지 반복
function agglomerative(E: number[][], nClusters: number): number[] {
  let clusters: number[][] = E.map((_, i) => [i]);
  while (clusters.length > nClusters) {
    let best: [number, number, number] = [0, 1, Infinity];
    for (let a = 0; a < clusters.length; a++) {
      for (let b = a + 1; b < clusters.length; b++) {
        let s = 0;
        for (const i of clusters[a]) for (const j of clusters[b]) s += cosDist(E[i], E[j]);
        const d = s / (clusters[a].length * clusters[b].length); // 묶음 사이 평균 거리
        if (d < best[2]) best = [a, b, d];
      }
    }
    const [a, b] = best;
    clusters = clusters.filter((_, k) => k !== a && k !== b).concat([[...clusters[a], ...clusters[b]]]);
  }
  const labels = new Array(E.length).fill(0);
  clusters.forEach((c, k) => c.forEach((i) => (labels[i] = k)));
  return labels;
}

const order = ["김팀장", "이연구원", "박대리", "김팀장", "이연구원", "박대리", "김팀장", "이연구원"]; // 8번 발화 (대본 순서)
let E = order.map((n) => embed(voice(VOICES[n] * (1 + 0.02 * randn()), 1.5 + 0.5 * uni())));
const meanE = E[0].map((_, j) => E.reduce((s, e) => s + e[j], 0) / E.length);
E = E.map((e) => e.map((v, j) => v - meanE[j]));

const N_SPK = 3; // 회의 참가자는 3명
const labels = agglomerative(E, N_SPK);
const names = Object.keys(VOICES);
console.log("정답     | " + [0, 1, 2].map((k) => `SPK_${k}`).join(" "));
for (const n of names) console.log(`${n.padEnd(6)} | ` + [0, 1, 2].map((k) => String(order.filter((o, i) => o === n && labels[i] === k).length).padStart(5)).join(" "));

// 번호는 임의이므로 가장 잘 맞는 이름 짝으로 정확도를 센다
const perms = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]];
const best = Math.max(...perms.map((p) => order.filter((o, i) => names[p[labels[i]]] === o).length));
console.log(`발화 ${order.length}개 중 ${best}개를 맞게 묶음 (${Math.round((best / order.length) * 100)}%)`);
check(N_SPK === 3 && new Set(labels).size === 3, "회의 참가자는 3명입니다.");
check(best === order.length, "목소리가 서로 많이 다르면 모든 발화를 맞게 묶어요.");

der.typescript:
// D9 · Part 5 · DER 계산기: 화자 분리를 몇 점으로 매기나 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_der.ts
//   DER = (놓친 말 + 없는 말 + 화자 혼동) / 전체 말 시간. 0.01초 격자에 정답·결과를 칠하고, 화자 번호를 가장 잘 맞는 짝으로 바꾼 뒤 세 가지 오류를 직접 센다
// 대체 경로: pyannote.metrics 의 DiarizationErrorRate 대신, 같은 정의를 격자 계산으로 직접 구현한다 (collar 0, 겹침 없음).
type Row = [number, number, string];
const STEP = 0.01; // 0.01초 격자

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const paint = (rows: Row[], total: number, ids: Record<string, number>): number[] => {
  const g = new Array(Math.round(total / STEP)).fill(-1); // -1 = 무음
  for (const [a, b, spk] of rows) for (let i = Math.round(a / STEP); i < Math.round(b / STEP); i++) g[i] = ids[spk];
  return g;
};

const permutations = (n: number): number[][] => {
  if (n === 1) return [[0]];
  return permutations(n - 1).flatMap((p) => Array.from({ length: n }, (_, pos) => [...p.slice(0, pos), n - 1, ...p.slice(pos)]));
};

function derParts(refRows: Row[], hypRows: Row[], total: number = 20): [number, number, number, number, number] {
  const idsOf = (rows: Row[]): Record<string, number> => Object.fromEntries([...new Set(rows.map((r) => r[2]))].sort().map((s, i) => [s, i]));
  const refIds = idsOf(refRows);
  const hypIds = idsOf(hypRows);
  const ref = paint(refRows, total, refIds);
  const hyp = paint(hypRows, total, hypIds);
  const k = Math.max(Object.keys(refIds).length, Object.keys(hypIds).length);
  let bestAgree = -1;
  let mapped: number[] = [];
  for (const perm of permutations(k)) {
    // 결과 화자 번호 -> 정답 화자 번호 가장 잘 맞는 짝
    const m = hyp.map((h) => (h >= 0 ? perm[h] : -1));
    const agree = m.filter((v, i) => v === ref[i] && ref[i] >= 0).length;
    if (agree > bestAgree) {
      bestAgree = agree;
      mapped = m;
    }
  }
  const count = (f: (r: number, h: number, m: number) => boolean): number => ref.filter((r, i) => f(r, hyp[i], mapped[i])).length * STEP;
  const miss = count((r, h) => r >= 0 && h < 0); // 놓친 말
  const fa = count((r, h) => r < 0 && h >= 0); // 없는 말을 만듦
  const conf = count((r, h, m) => r >= 0 && h >= 0 && m !== r); // 화자를 잘못 붙임
  const totalSpeech = ref.filter((r) => r >= 0).length * STEP;
  return [miss, fa, conf, totalSpeech, (miss + fa + conf) / totalSpeech];
}

const REF: Row[] = [[0, 4, "김팀장"], [4.5, 8.5, "이연구원"], [9, 12, "박대리"], [13, 16, "김팀장"]];
const HYP: Row[] = [
  [0, 3.5, "A"], // 마지막 0.5초 놓침
  [4.5, 8.5, "B"], // 완벽
  [9, 10.5, "C"], [10.5, 12, "A"], // 뒤 1.5초를 다른 사람으로 혼동
  [12.7, 13, "B"], // 말이 없는 0.3초를 만들어 냄
  [13, 16, "A"],
];
const [miss, fa, conf, tot, der] = derParts(REF, HYP);
console.log(`놓친 말 ${miss.toFixed(2)}초 + 없는 말 ${fa.toFixed(2)}초 + 혼동 ${conf.toFixed(2)}초 = ${(miss + fa + conf).toFixed(2)}초 / 전체 말 ${tot.toFixed(1)}초`);
console.log(`DER = ${(der * 100).toFixed(1)}%`);
check(Math.abs(miss - 0.5) < 1e-6 && Math.abs(fa - 0.3) < 1e-6 && Math.abs(conf - 1.5) < 1e-6, "세 가지 오류는 놓친 말 · 없는 말 · 혼동(confusion) 이에요.");
check(Math.abs(der - 2.3 / 14) < 1e-6, "DER = (놓친 + 없는 + 혼동) / 전체 말 시간 이에요.");
const rename: Record<string, string> = { 김팀장: "X", 이연구원: "Y", 박대리: "Z" };
check(derParts(REF, REF.map(([a, b, s]): Row => [a, b, rename[s]]))[4] === 0, "화자 이름이 달라도 구간이 같으면 DER 은 0 이에요.");

assign.typescript:
// D9 · Part 6 · 단어에 화자 붙이기 · 번호에 이름 붙이기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_assign.ts
//   단어의 [시작, 끝] 과 가장 많이 겹치는 화자 구간의 번호를 붙이고(겹침이 없으면 가장 가까운 화자), 화자 번호 ↔ 이름을 겹치지 않게 짝짓는다(순열을 전부 보는 최적 짝짓기)
// 대체 경로: whisperx.assign_word_speakers 와 ECAPA 임베딩 대신, 같은 규칙(최대 겹침 · fill_nearest)을 직접 구현하고 등록 음성 유사도는 손으로 적은 표를 쓴다.
type Word = [string, number, number];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const DIAR: [number, number, string][] = [[0.0, 3.0, "SPK_0"], [3.2, 6.0, "SPK_1"], [6.5, 9.0, "SPK_2"], [9.2, 12.0, "SPK_0"]]; // 화자 분리 결과
const WORDS: Word[] = [
  ["오늘", 0.2, 0.8], ["회의는", 0.9, 1.6], ["시작합니다", 1.8, 2.9], // 정답: 김팀장
  ["모델은", 3.3, 3.9], ["정했습니다", 4.0, 5.2], // 이연구원
  ["그런데", 6.6, 7.2], ["구분이", 7.3, 8.0], ["안", 8.1, 8.4], ["됩니다", 8.45, 9.0], // 박대리
  ["그래서", 9.3, 10.0], ["붙입니다", 10.1, 11.5], // 김팀장
  ["네", 3.05, 3.15], // 구간 사이 틈에 떨어진 단어
];

const overlap = (a0: number, a1: number, b0: number, b1: number): number => Math.max(0, Math.min(a1, b1) - Math.max(a0, b0));

function assign([, s, e]: Word): string {
  let best: [number, string] = [0, ""];
  for (const [a, b, spk] of DIAR) {
    const ov = overlap(s, e, a, b);
    if (ov > best[0]) best = [ov, spk];
  }
  if (best[0] > 0) return best[1]; // 가장 많이 겹치는 화자
  const mid = (s + e) / 2; // 겹침이 없으면 가장 가까운 구간의 화자 (fill_nearest)
  const dist = (d: [number, number, string]): number => Math.min(Math.abs(mid - d[0]), Math.abs(mid - d[1]));
  return DIAR.reduce((b, d) => (dist(d) < dist(b) ? d : b))[2];
}

const got = WORDS.map(assign);
WORDS.slice(0, 5).forEach((w, i) => console.log(`  ${w[0]} ${w[1].toFixed(2)} ~ ${w[2].toFixed(2)}  ${got[i]}`));
console.log("틈에 떨어진 단어 '네':", got[got.length - 1]);
const want = [...Array(3).fill("SPK_0"), ...Array(2).fill("SPK_1"), ...Array(4).fill("SPK_2"), ...Array(2).fill("SPK_0")];
check(got.slice(0, -1).join() === want.join(), "단어와 가장 많이 겹치는 화자 구간의 번호를 붙여요.");
check(got[got.length - 1] === "SPK_0" || got[got.length - 1] === "SPK_1", "겹치는 구간이 없으면 가장 가까운 화자에게 붙어요.");

// 번호 -> 이름: 등록 음성 유사도 표에서 겹치지 않게 가장 잘 맞는 짝 (순열 전부 비교)
const labels = ["SPK_0", "SPK_1", "SPK_2"];
const names = ["김팀장", "이연구원", "박대리"];
const sim = [
  [0.82, 0.21, 0.3], // SPK_0 은 김팀장과 가장 닮음
  [0.25, 0.77, 0.4],
  [0.45, 0.33, 0.69],
];
const perms = [[0, 1, 2], [0, 2, 1], [1, 0, 2], [1, 2, 0], [2, 0, 1], [2, 1, 0]];
const score = (p: number[]): number => p.reduce((s, j, i) => s + sim[i][j], 0);
const bestPerm = perms.reduce((b, p) => (score(p) > score(b) ? p : b));
const NAME: Record<string, string> = Object.fromEntries(labels.map((l, i) => [l, names[bestPerm[i]]]));
console.log("이름 붙이기:", JSON.stringify(NAME));
const truth = [...Array(3).fill("김팀장"), ...Array(2).fill("이연구원"), ...Array(4).fill("박대리"), ...Array(2).fill("김팀장")];
const ok = got.slice(0, -1).map((g, i) => NAME[g] === truth[i]);
console.log(`단어별 화자 정확도: ${Math.round((ok.filter(Boolean).length / ok.length) * 100)}% (${ok.filter(Boolean).length}/${ok.length} 단어)`);
check(NAME["SPK_0"] === "김팀장" && NAME["SPK_1"] === "이연구원" && NAME["SPK_2"] === "박대리" && ok.length === 11 && ok.every(Boolean), "번호와 이름은 1:1 로 짝지어져야 해요.");

minutes.typescript:
// D9 · Part 6 · 회의록 만들기: 같은 화자의 단어를 한 줄로 묶기 — 단독 실행 완성 코드 (Node 26 · TypeScript)
// 설치 불필요 (Node 내장만)
// 실행: node --experimental-strip-types d09_minutes.ts
//   화자가 붙은 단어 열을 화자가 바뀔 때마다 한 줄로 묶어 `[mm:ss.xx] 이름: 문장` 회의록과 SRT 자막 시각을 만든다
// 대체 경로: 받아쓰기·정렬·화자 분리 결과 대신, 화자가 이미 붙은 단어 목록을 손으로 적어 둔다.
type Line = { speaker: string; start: number; end: number; text: string };

const WORDS: [string, number, number, string][] = [
  ["오늘", 0.2, 0.8, "김팀장"], ["회의는", 0.9, 1.6, "김팀장"], ["시작합니다", 1.8, 2.9, "김팀장"],
  ["모델은", 3.3, 3.9, "이연구원"], ["정했습니다", 4.0, 5.2, "이연구원"],
  ["그런데", 6.6, 7.2, "박대리"], ["구분이", 7.3, 8.0, "박대리"], ["안", 8.1, 8.4, "박대리"], ["됩니다", 8.45, 9.0, "박대리"],
  ["그래서", 9.3, 10.0, "김팀장"], ["붙입니다", 10.1, 11.5, "김팀장"],
];

function check(cond: boolean, hint: string = "정답을 다시 확인하세요."): void {
  // 정답 확인 도우미: 조건이 맞으면 정답, 아니면 힌트를 보여 준다
  console.log(cond ? "[정답] 정답입니다!" : `[다시] ${hint}`);
}

const minutes: Line[] = [];
for (const [word, start, end, spk] of WORDS) {
  const last = minutes[minutes.length - 1];
  if (last && last.speaker === spk) {
    // 이번 단어의 화자와 같으면 이어 붙이기
    last.text += " " + word;
    last.end = end;
  } else {
    minutes.push({ speaker: spk, start, end, text: word });
  }
}

const p2 = (n: number): string => String(n).padStart(2, "0");
for (const m of minutes) console.log(`[${p2(Math.floor(m.start / 60))}:${(m.start % 60).toFixed(2).padStart(5, "0")}] ${m.speaker}: ${m.text}`);
check(minutes.length === 4 && minutes.every((m, i) => i === 0 || m.speaker !== minutes[i - 1].speaker), "이번 단어의 화자 spk 와 비교합니다.");

function srtTime(t: number): string {
  let ms = Math.round(t * 1000);
  const h = Math.floor(ms / 3_600_000);
  ms %= 3_600_000;
  const m = Math.floor(ms / 60_000);
  ms %= 60_000;
  const s = Math.floor(ms / 1000);
  ms %= 1000;
  return `${p2(h)}:${p2(m)}:${p2(s)},${String(ms).padStart(3, "0")}`;
}

const srt = minutes.map((m, i) => `${i + 1}\n${srtTime(m.start)} --> ${srtTime(m.end)}\n${m.speaker}: ${m.text}\n`).join("\n");
console.log(srt.split("\n\n")[0]);
check(srtTime(3.25) === "00:00:03,250" && minutes[0].text === "오늘 회의는 시작합니다" && minutes[2].end === 9.0, "같은 화자 단어는 한 줄, 끝 시각은 마지막 단어의 끝이에요.");
